def valid_nspid(status_lines, self_pid):
    fields = [line.split(':', 1)[1].split() for line in status_lines if line.startswith('NSpid:')]
    if len(fields) != 1 or not fields[0]:
        return False
    if any(not token.isdecimal() or int(token) <= 0 for token in fields[0]):
        return False
    return int(fields[0][-1]) == self_pid
